const PROCESSING_FEE = 5;

/**
 * The first-insurance surcharge is +10%, applied as the exact ratio 11/10
 * rather than a 1.1 multiplier. Floating-point `100 * 1.1` is
 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
 * instead of 115 G. Multiplying before dividing keeps the arithmetic exact.
 */
const FIRST_INSURANCE_SURCHARGE = { numerator: 11, denominator: 10 };

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * FIRST_INSURANCE_SURCHARGE.numerator) /
  FIRST_INSURANCE_SURCHARGE.denominator;

/** All rounding is in the MHPCO's favor — always up. */
const roundInMHPCOsFavor = Math.ceil;

